// SourceDocument starts a query for related objects on source_documents
func (o *SourceObservation) SourceDocument(mods ...bob.Mod[*dialect.SelectQuery]) SourceDocumentsQuery {
	return SourceDocuments.Query(append(mods,
		sm.Where(SourceDocuments.Columns.HouseholdID.EQ(psql.Arg(o.HouseholdID))), sm.Where(SourceDocuments.Columns.ID.EQ(psql.Arg(o.SourceDocumentID))),
	)...)
}

func (os SourceObservationSlice) SourceDocument(mods ...bob.Mod[*dialect.SelectQuery]) SourceDocumentsQuery {
	pkHouseholdID := make(pgtypes.Array[uuid.UUID], 0, len(os))

	pkSourceDocumentID := make(pgtypes.Array[uuid.UUID], 0, len(os))

	for _, o := range os {
		if o == nil {
			continue
		}
		pkHouseholdID = append(pkHouseholdID, o.HouseholdID)
		pkSourceDocumentID = append(pkSourceDocumentID, o.SourceDocumentID)
	}

	return SourceDocuments.Query(append(mods,
		sm.InnerJoin(psql.Select(
			sm.Distinct(),
			sm.Columns(psql.Quote("bob_rel_keys_src", "HouseholdID"), psql.Quote("bob_rel_keys_src", "ID")),
			sm.From(psql.F("unnest", psql.Cast(psql.Arg(pkHouseholdID), "uuid[]"), psql.Cast(psql.Arg(pkSourceDocumentID), "uuid[]"))).As("bob_rel_keys_src", "HouseholdID", "ID"),
		)).As("bob_rel_keys").On(SourceDocuments.Columns.HouseholdID.EQ(psql.Quote("bob_rel_keys", "HouseholdID")), SourceDocuments.Columns.ID.EQ(psql.Quote("bob_rel_keys", "ID"))),
	)...)
}

func attachSourceObservationSourceDocument0(ctx context.Context, exec bob.Executor, count int, sourceObservation0 *SourceObservation, sourceDocument1 *SourceDocument) (*SourceObservation, error) {
	setter := &SourceObservationSetter{
		HouseholdID:      func() *uuid.UUID { return &sourceDocument1.HouseholdID }(),
		SourceDocumentID: func() *uuid.UUID { return &sourceDocument1.ID }(),
	}

	err := sourceObservation0.Update(ctx, exec, setter)
	if err != nil {
		return nil, fmt.Errorf("attachSourceObservationSourceDocument0: %w", err)
	}

	return sourceObservation0, nil
}

func (sourceObservation0 *SourceObservation) InsertSourceDocument(ctx context.Context, exec bob.Executor, related *SourceDocumentSetter) error {
	var err error

	sourceDocument1, err := SourceDocuments.Insert(related).One(ctx, exec)
	if err != nil {
		return fmt.Errorf("inserting related objects: %w", err)
	}

	_, err = attachSourceObservationSourceDocument0(ctx, exec, 1, sourceObservation0, sourceDocument1)
	if err != nil {
		return err
	}

	sourceObservation0.R.SourceDocument = sourceDocument1
	sourceObservation0.R.Loaded.SourceDocument = true

	sourceDocument1.R.SourceObservations = append(sourceDocument1.R.SourceObservations, sourceObservation0)

	return nil
}

func (sourceObservation0 *SourceObservation) AttachSourceDocument(ctx context.Context, exec bob.Executor, sourceDocument1 *SourceDocument) error {
	var err error

	_, err = attachSourceObservationSourceDocument0(ctx, exec, 1, sourceObservation0, sourceDocument1)
	if err != nil {
		return err
	}

	sourceObservation0.R.SourceDocument = sourceDocument1
	sourceObservation0.R.Loaded.SourceDocument = true

	sourceDocument1.R.SourceObservations = append(sourceDocument1.R.SourceObservations, sourceObservation0)

	return nil
}

