// sourceObservationWhereR holds the relationship-based filters of
// sourceObservationWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type sourceObservationWhereR[Q psql.Filterable] struct {
	cols sourceObservationColumns
}

// HasSourceDocument filters parents that have a matching SourceDocument using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to SourceDocuments).
func (w sourceObservationWhereR[Q]) HasSourceDocument(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(SourceDocuments.NameExpr()),
		sm.Where(SourceDocuments.Columns.HouseholdID.EQ(w.cols.HouseholdID)),
		sm.Where(SourceDocuments.Columns.ID.EQ(w.cols.SourceDocumentID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

func (o *SourceObservation) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "SourceDocument":
		rel, ok := retrieved.(*SourceDocument)
		if !ok {
			return fmt.Errorf("sourceObservation cannot load %T as %q", retrieved, name)
		}

		o.R.SourceDocument = rel
		o.R.Loaded.SourceDocument = true

		if rel != nil {
			rel.R.SourceObservations = SourceObservationSlice{o}
		}
		return nil
	default:
		return fmt.Errorf("sourceObservation has no relationship %q", name)
	}
}

