// LoadSourceDocument loads the sourceObservation's SourceDocument into the .R struct
func (o *SourceObservation) LoadSourceDocument(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.SourceDocument = nil
	o.R.Loaded.SourceDocument = false

	related, err := o.SourceDocument(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.SourceObservations = SourceObservationSlice{o}

	o.R.SourceDocument = related
	o.R.Loaded.SourceDocument = true
	return nil
}

// LoadSourceDocument loads the sourceObservation's SourceDocument into the .R struct
func (os SourceObservationSlice) LoadSourceDocument(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	sourceDocuments, err := os.SourceDocument(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.SourceDocument = nil
		o.R.Loaded.SourceDocument = true
	}
	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range sourceDocuments {

			if !(o.HouseholdID == rel.HouseholdID) {
				continue
			}

			if !(o.SourceDocumentID == rel.ID) {
				continue
			}

			rel.R.SourceObservations = append(rel.R.SourceObservations, o)

			o.R.SourceDocument = rel
			break
		}
	}

	return nil
}

type sourceObservationJoins[Q dialect.Joinable] struct {
	typ            string
	SourceDocument modAs[Q, sourceDocumentColumns]
}

func (j sourceObservationJoins[Q]) aliasedAs(alias string) sourceObservationJoins[Q] {
	return buildSourceObservationJoins[Q](buildSourceObservationColumns(alias), j.typ)
}

func buildSourceObservationJoins[Q dialect.Joinable](cols sourceObservationColumns, typ string) sourceObservationJoins[Q] {
	return sourceObservationJoins[Q]{
		typ: typ,
		SourceDocument: modAs[Q, sourceDocumentColumns]{
			c: SourceDocuments.Columns,
			f: func(to sourceDocumentColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, SourceDocuments.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.ID.EQ(cols.SourceDocumentID),
					))
				}

				return mods
			},
		},
	}
}
